add_action('rest_api_init', function () {

    register_rest_route('enishi/v1', '/livekit-token', [
        'methods' => 'GET',
        'permission_callback' => '__return_true',
        'callback' => function ($request) {

            $room = sanitize_text_field(
                $request->get_param('room') ?: 'enishi-main'
            );
            $role = sanitize_text_field(
                $request->get_param('role') ?: 'viewer'
            );

            $user = wp_get_current_user();
            if ($user && $user->ID > 0) {
                $identity = 'user_' . $user->ID . '_' . sanitize_key($user->user_login ?: $user->ID);
                $name     = $user->display_name ?: $user->user_login;
            } else {
                $guest_suffix = substr(md5((string) wp_rand() . ($_SERVER['REMOTE_ADDR'] ?? '')), 0, 6);
                $identity     = 'guest_' . $guest_suffix;
                $name         = 'Guest ' . strtoupper($guest_suffix);
            }

            $can_publish = ($role === 'host' && $user && $user->ID > 0);

            return [
                'url'      => 'wss://live.pt-solution.vn',
                'room'     => $room,
                'identity' => $identity,
                'name'     => $name,
                'token'    => enishi_generate_livekit_token(
                    $room,
                    $identity,
                    $can_publish,
                    $name
                )
            ];
        }
    ]);
});

function enishi_generate_livekit_token($room, $identity, $can_publish = true, $name = '')
{
    $apiKey = 'ENISHI';
    $apiSecret = 'd8f8d3f9a2f4a3c8e7b1d5f6a9c2e4b7d1f8c3a6e9b2f5d7a4c1e8f6b3d9a2';

    $header = [
        'alg' => 'HS256',
        'typ' => 'JWT'
    ];

    $payload = [
        'iss'  => $apiKey,
        'sub'  => (string) $identity,
        'name' => $name !== '' ? $name : (string) $identity,
        'nbf'  => time() - 10,
        'exp'  => time() + 7200,
        'video' => [
            'roomJoin'     => true,
            'room'         => $room,
            'canPublish'   => (bool) $can_publish,
            'canSubscribe' => true,
            'canPublishData' => true,
        ]
    ];

    $headerEncoded = rtrim(
        strtr(base64_encode(json_encode($header)), '+/', '-_'),
        '='
    );

    $payloadEncoded = rtrim(
        strtr(base64_encode(json_encode($payload)), '+/', '-_'),
        '='
    );

    $signature = hash_hmac(
        'sha256',
        $headerEncoded . '.' . $payloadEncoded,
        $apiSecret,
        true
    );

    $signatureEncoded = rtrim(
        strtr(base64_encode($signature), '+/', '-_'),
        '='
    );

    return $headerEncoded . '.' . $payloadEncoded . '.' . $signatureEncoded;
}
add_action('wp_ajax_get_user_photos', 'get_user_photos');

function get_user_photos()
{
    if (!is_user_logged_in()) {
        wp_send_json_error('Login required');
    }

    $user = wp_get_current_user();

    $upload_dir = wp_upload_dir();

    $folder_path = $upload_dir['basedir'] .
        '/place-media/' . $user->user_login;

    $folder_url = $upload_dir['baseurl'] .
        '/place-media/' . $user->user_login;

    $photos = [];

    if (is_dir($folder_path)) {

        $files = glob($folder_path . '/*.{jpg,jpeg,png,webp,gif,JPG,JPEG,PNG,WEBP,GIF}', GLOB_BRACE);

        foreach ($files as $file) {

            $photos[] = [
                'name' => basename($file),
                'url'  => $folder_url . '/' . basename($file)
            ];
        }
    }

    wp_send_json_success($photos);
}

