add_filter('buddynext_nav_items', 'pt_buddynext_add_balance_tab', 20, 2);
function pt_buddynext_add_balance_tab($items, $ctx)
{
    if (!is_array($items) || !is_object($ctx) || ($ctx->surface ?? '') !== 'profile') {
        return $items;
    }

    $subject_id = (int) ($ctx->subject_id ?? 0);
    $viewer_id  = (int) ($ctx->viewer_id ?? 0);
    if (!$subject_id || ($subject_id !== $viewer_id && !current_user_can('manage_options'))) {
        return $items;
    }

    $items[] = [
        'id'       => 'balance',
        'surface'  => 'profile',
        'layer'    => 'primary',
        'label'    => __('Balance', 'buddyx-child'),
        'tab'      => 'balance',
        'priority' => 90,
    ];

    return $items;
}

